// Audio is generated by Kokoro on this Mac. No browser voice or external speech service.
export class LocalNarration {
 constructor(){this.context=null;this.controller=null;this.source=null;this.cancelPlayback=null;this.version=0;this.cache=new Map();}
 supported(){return typeof window!=='undefined'&&!!(window.AudioContext||window.webkitAudioContext);}
 unlock(){const Context=window.AudioContext||window.webkitAudioContext;this.context??=new Context();return this.context.resume();}
 stop(){this.version++;this.controller?.abort();this.controller=null;this.cancelPlayback?.();this.cancelPlayback=null;try{this.source?.stop();}catch{}this.source?.disconnect();this.source=null;}
 async load(text,signal){
  if(this.cache.has(text))return this.cache.get(text);
  const response=await fetch('/api/voice/speak',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text}),signal});
  if(!response.ok){let message='Could not prepare the local voice. Please try again.';try{message=(await response.json()).error||message;}catch{}throw Error(message);}
  const bytes=await response.arrayBuffer();if(signal.aborted)throw new DOMException('Stopped','AbortError');
  const audio=await this.context.decodeAudioData(bytes);if(signal.aborted)throw new DOMException('Stopped','AbortError');
  this.cache.set(text,audio);while(this.cache.size>12)this.cache.delete(this.cache.keys().next().value);return audio;
 }
 async play(text,{onStart=()=>{},nextText}={}){
  const version=this.version;await this.unlock();if(version!==this.version)return;
  const controller=new AbortController();this.controller=controller;
  const buffer=await this.load(text,controller.signal);if(version!==this.version)return;
  await new Promise((resolve,reject)=>{
   const source=this.context.createBufferSource();source.buffer=buffer;source.connect(this.context.destination);this.source=source;
   this.cancelPlayback=resolve;
   source.onended=()=>{source.disconnect();if(this.source===source)this.source=null;if(this.cancelPlayback===resolve)this.cancelPlayback=null;resolve();};
   try{source.start();onStart();}catch(error){reject(error);}
  });
 }
 prefetch(text){if(!text||!this.context)return;const signal=this.controller?.signal;if(!signal||signal.aborted)return;this.load(text,signal).catch(()=>{});}
}
